<?php declare(strict_types=1); ?>
<div class="grid-2"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Controlled document exchange</span><h2>Submit document reference</h2><p>Document metadata and controlled references are accepted. Raw uploads remain disabled until malware scanning and protected download storage are configured.</p></div></header><?php if(supplier_portal_can($account,'submit_documents')): ?><form class="form-grid" method="post" action="<?= h(root_url('supplier-portal/action.php')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="submit_document"><input type="hidden" name="return_tab" value="documents"><label><span>Document type</span><select name="document_type"><?php foreach(['insurance_certificate','tax_document','quality_certification','safety_document','contract_attachment','warranty_document','product_specification','corrective_action_evidence','shipment_document','invoice_document','banking_change_request','other'] as $type): ?><option value="<?= h($type) ?>"><?= h(status_label($type)) ?></option><?php endforeach; ?></select></label><label><span>Record type</span><select name="entity_type"><option value="supplier">Supplier</option><option value="purchase_order">Purchase order</option><option value="invoice">Invoice</option><option value="quality">Quality</option></select></label><label><span>Record ID</span><input type="number" name="entity_id" value="<?= (int)$account['supplier_id'] ?>"></label><label><span>Title</span><input name="title" required></label><label class="span-2"><span>Controlled document reference</span><input name="document_reference" required></label><label><span>Effective date</span><input type="date" name="effective_date"></label><label><span>Expiration date</span><input type="date" name="expiration_date"></label><div class="span-2"><button class="button primary">Submit document reference</button></div></form><?php endif; ?></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Document ledger</span><h2>Review and expiration status</h2></div></header><div class="record-list"><?php foreach($documents as $document): ?><article class="record-card"><header><div><strong><?= h($document['title']) ?></strong><small><?= h(status_label($document['document_type'])) ?> · <?= h($document['document_reference']) ?></small></div><span class="status <?= h($document['status']) ?>"><?= h(status_label($document['status'])) ?></span></header><p><?= $document['expiration_date']?'Expires '.h(date_us($document['expiration_date'])):'No expiration date' ?>. <?= h($document['review_note']??'') ?></p></article><?php endforeach; ?></div></section></div>
